action.command:
awk '
/^[[:space:]]*;/ || /^[[:space:]]*#/ || /^[[:space:]]*$/ { next }
/^\[[^]]+\][[:space:]]*$/ { print "SECTION " $0; next }
/^[[:space:]]*[^=:#[:space:]][^=:#]*[[:space:]]*[:=]/ {
  line=$0; sub(/^[[:space:]]*/, "", line); key=line; sub(/[[:space:]]*[:=].*$/, "", key); sub(/[[:space:]]+$/, "", key); print "KEY " key; next
}
' app_config.ini

